function polygon(points,fill){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill()}
function drawBackground(){let grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#233c55');grad.addColorStop(.52,'#718b98');grad.addColorStop(1,'#d4cbb2');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
// distant alpine ridgelines
let shift=cameraY*.035;for(let layer=0;layer<3;layer++){let base=H*(.51+layer*.13);let pts=[[-30,H]];for(let x=-80;x<W+120;x+=110){let peak=base-((Math.sin(x*.014+layer*4)*.5+.5)*90+35+layer*28);pts.push([x,peak],[x+52,peak-30-Math.sin(x*.042)*22],[x+110,base+10])}pts.push([W+40,H]);polygon(pts,['#718897','#526d7d','#334a5a'][layer]);}
// cloud bands
ctx.globalAlpha=.12;for(let i=0;i<5;i++){let x=((i*277-elapsed*8)% (W+280))-100;ctx.fillStyle='#f3f5ef';ctx.beginPath();ctx.ellipse(x,95+i*75,W*.18,17+i%3*5,0,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
// far below, atmospheric fog
let fog=ctx.createLinearGradient(0,H*.52,0,H);fog.addColorStop(0,'#d3d4c8');fog.addColorStop(1,'#d3d4c800');ctx.fillStyle=fog;ctx.fillRect(0,H*.45,W,H*.55);
}
function drawCliff(){let sx=W/worldW,baseY=worldToScreenY(0);ctx.save();ctx.scale(sx,1);
// immense dark rock walls, framing the climbing route
let shift=(cameraY*.12)%370;for(let side=0;side<2;side++){let x=side===0?-90:885;let direction=side===0?1:-1;let pts=[[x,-600],[x+direction*230,-600]];for(let y=-600;y<H+550;y+=70){let wobble=Math.sin((y+shift)*.023+side*2)*28+Math.sin(y*.061+side)*15;pts.push([x+direction*(180+wobble),y+shift%70],[x+direction*(95+Math.sin(y*.041+2)*20),y+35+shift%70])}pts.push([x,H+700],[x-200,H+700]);polygon(pts,side===0?'#344653':'#263845');}
// angled cliff facets
for(let i=0;i<22;i++){let y=((i*183-cameraY*.2)% (H+200))-100;let side=i%2;let x=side?850:20;polygon([[x,y],[x+(side?-90:110),y+42],[x+(side?-20:55),y+150],[x,y+118]],i%3===0?'#415360':'#394b57')}
ctx.restore();
}
function drawWorld(){let sx=W/worldW;ctx.save();ctx.scale(sx,1);
// ascent route dotted guide
ctx.beginPath();ctx.setLineDash([3,14]);ctx.lineWidth=1.5/sx;ctx.strokeStyle='#c2eff066';let route=platforms.filter((_,i)=>i%3===0);route.forEach((p,i)=>{let y=worldToScreenY(p.y-8);if(i===0)ctx.moveTo(p.x,y);else ctx.lineTo(p.x,y)});ctx.stroke();ctx.setLineDash([]);
for(const p of platforms){let y=worldToScreenY(p.y);if(y<-70||y>H+70)continue;let x=p.x-p.w/2;
// platform shadow and rock ledge
ctx.fillStyle='#152630aa';ctx.beginPath();ctx.moveTo(x-3,y+8);ctx.lineTo(x+p.w+9,y+8);ctx.lineTo(x+p.w-5,y+29);ctx.lineTo(x+13,y+25);ctx.closePath();ctx.fill();ctx.fillStyle=p.summit?'#566976':'#4c5a5e';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+p.w,y);ctx.lineTo(x+p.w-8,y+18);ctx.lineTo(x+12,y+15);ctx.closePath();ctx.fill();ctx.fillStyle=p.summit?'#e7f0eb':'#d6ded8';ctx.beginPath();ctx.moveTo(x-2,y);ctx.lineTo(x+15,y-4);ctx.lineTo(x+p.w*.37,y-2);ctx.lineTo(x+p.w*.52,y+3);ctx.lineTo(x+p.w*.71,y-2);ctx.lineTo(x+p.w+3,y);ctx.lineTo(x+p.w-3,y+7);ctx.lineTo(x,y+5);ctx.closePath();ctx.fill();
if(p.checkpoint){ctx.strokeStyle='#b8f1ee';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,y-3);ctx.lineTo(p.x,y-41);ctx.stroke();polygon([[p.x,y-40],[p.x+19,y-34],[p.x,y-28]],'#9fe6e9');ctx.fillStyle='#e7ffff';ctx.font=`${10/sx}px monospace`;ctx.fillText('PITON',p.x+12,y-44)}
if(p.summit){ctx.fillStyle='#f1efdf';ctx.font=`bold ${17/sx}px Manrope`;ctx.textAlign='center';ctx.fillText('SUMMIT · 4,810 M',p.x,y-20);ctx.textAlign='left'}
}
for(const c of caches){if(c.got)continue;let y=worldToScreenY(c.y)+Math.sin(elapsed*3+c.phase)*4;ctx.save();ctx.translate(c.x,y);ctx.fillStyle='#d3bd83';ctx.fillRect(-10,-9,20,17);ctx.fillStyle='#f0dfae';ctx.fillRect(-10,-9,20,5);ctx.strokeStyle='#8c7953';ctx.lineWidth=1.5;ctx.strokeRect(-10,-9,20,17);ctx.fillStyle='#fff4c9';ctx.font=`${13/sx}px monospace`;ctx.textAlign='center';ctx.fillText('+',0,4);ctx.restore()}
ctx.restore();}
function drawPlayer(){let sx=W/worldW,px=player.x*sx,py=worldToScreenY(player.y),s=Math.max(.68,Math.min(1.35,W/950));ctx.save();ctx.translate(px,py);ctx.scale(sx*s,s);let run=Math.sin(player.anim)*Math.min(1,Math.abs(player.vx)/150),c=player.invuln>0&&Math.floor(elapsed*15)%2?'#efffff':'#e7dfc8';
// soft glow
ctx.fillStyle='#d4f0e822';ctx.beginPath();ctx.ellipse(0,2,22,32,0,0,Math.PI*2);ctx.fill();
// limbs behind body
ctx.strokeStyle='#182a37';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-2,9);ctx.lineTo(-7+run*7,20);ctx.lineTo(-10-run*5,28);ctx.moveTo(2,9);ctx.lineTo(7-run*7,19);ctx.lineTo(10+run*5,28);ctx.stroke();ctx.strokeStyle='#dfd5ba';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-11-run*5,28);ctx.lineTo(-4-run*5,28);ctx.moveTo(10+run*5,28);ctx.lineTo(16+run*5,28);ctx.stroke();
// backpack
ctx.fillStyle='#c47750';ctx.beginPath();ctx.roundRect(-12,-12,9,20,3);ctx.fill();ctx.fillStyle='#e3a06b';ctx.fillRect(-11,-9,7,3);
// torso and head
ctx.fillStyle=c;ctx.beginPath();ctx.roundRect(-7,-16,15,25,5);ctx.fill();ctx.fillStyle='#b94f39';ctx.fillRect(-6,-11,13,9);ctx.fillStyle='#e2b991';ctx.beginPath();ctx.arc(1,-22,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e8a847';ctx.beginPath();ctx.arc(1,-25,8,Math.PI,Math.PI*2);ctx.lineTo(9,-20);ctx.lineTo(-7,-20);ctx.fill();
// arms and ice axe, raised while climbing
ctx.strokeStyle='#e2b991';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-5,-11);ctx.lineTo(-11,-19+Math.sin(player.anim)*2);ctx.lineTo(-15,-27);ctx.moveTo(6,-11);ctx.lineTo(11,-20-Math.sin(player.anim)*2);ctx.lineTo(16,-26);ctx.stroke();ctx.strokeStyle='#a9e3ed';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(16,-26);ctx.lineTo(19,-38);ctx.moveTo(14,-35);ctx.lineTo(23,-36);ctx.stroke();ctx.restore();}
function drawParticles(){for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x*W/worldW,worldToScreenY(p.y),2.3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}
function draw(){drawBackground();drawCliff();drawWorld();drawPlayer();drawParticles();
// altitude marker ticks on screen edge
let progress=clamp((3300-player.y)/3300,0,1);ctx.fillStyle='#e5f4ed77';ctx.fillRect(W-12,0,1,H);ctx.fillStyle='#b6edf0';ctx.fillRect(W-14,H*(1-progress),5,1.5);
}
function loop(t){let dt=Math.min(.034,(t-last)/1000||0);last=t;update(dt);draw();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}requestAnimationFrame(loop)}
requestAnimationFrame(loop);
})();
</script>
